BEGIN TRANSACTION READ ONLY;
SET LOCAL statement_timeout = '8s';
WITH wanted(schema_name,function_name) AS (VALUES ('public','claim_starter_board_jobs'),('public','finish_starter_board_job'),('fhfh_internal','enqueue_starter_board_game'),('fhfh_internal','enqueue_starter_board_observation'),('fhfh_internal','enqueue_starter_board_resolution'),('public','enqueue_forge_cadence_slot'),('fhfh_internal','advance_forge_cadence_slots'))
SELECT w.schema_name,w.function_name,p.oid IS NOT NULL AS exists,
 CASE WHEN p.oid IS NOT NULL THEN pg_catalog.pg_get_function_identity_arguments(p.oid) END AS identity_arguments,
 CASE WHEN p.oid IS NOT NULL THEN pg_catalog.pg_get_function_result(p.oid) END AS result_type,
 pg_catalog.pg_get_userbyid(p.proowner) AS owner,p.prosecdef AS security_definer,p.provolatile AS volatility,p.proconfig AS settings,p.proacl::text AS acl,
 CASE WHEN p.oid IS NOT NULL THEN octet_length(pg_catalog.pg_get_functiondef(p.oid))>65536 ELSE false END AS over_definition_byte_limit,
 CASE WHEN p.oid IS NOT NULL AND octet_length(pg_catalog.pg_get_functiondef(p.oid))<=65536 THEN pg_catalog.pg_get_functiondef(p.oid) END AS definition
FROM wanted w LEFT JOIN pg_catalog.pg_namespace n ON n.nspname=w.schema_name
LEFT JOIN pg_catalog.pg_proc p ON p.pronamespace=n.oid AND p.proname=w.function_name AND p.prokind IN ('f','p')
ORDER BY w.schema_name,w.function_name,identity_arguments LIMIT 17;
COMMIT;

BEGIN TRANSACTION READ ONLY;
SET LOCAL statement_timeout = '8s';
SELECT q.game_id,q.version,q.claimed_version,q.status,q.first_accepted_at,q.last_accepted_at,q.source_published_at,q.received_at,q.not_before,q.lease_owner,q.lease_expires_at,q.dispatched_at,q.completed_at,q.active_run_id,q.published_run_id,q.attempt_count,
 g."startTime" AS scheduled_start_at,
 q.lease_expires_at>statement_timestamp() AS lease_unexpired,
 (SELECT r.status FROM public.forge_runs r WHERE r.run_id=q.active_run_id) AS active_run_status,
 EXISTS(SELECT 1 FROM public.forge_game_revisions r WHERE r.game_id=q.game_id AND r.run_id=q.active_run_id) AS active_run_has_revision,
 EXISTS(SELECT 1 FROM public.forge_game_revisions r WHERE r.game_id=q.game_id AND r.run_id=q.published_run_id) AS published_run_has_revision,
 statement_timestamp() AS observed_at
FROM public.forge_game_update_queue q LEFT JOIN public.games g ON g.id=q.game_id
WHERE q.status='running' OR q.status IN ('pending','failed') AND g."startTime">statement_timestamp()
ORDER BY CASE WHEN q.status='running' THEN 0 ELSE 1 END,q.first_accepted_at,q.game_id LIMIT 65;
COMMIT;

BEGIN TRANSACTION READ ONLY;
SET LOCAL statement_timeout = '8s';
WITH target(schema_name,table_name) AS (VALUES ('public','forge_game_update_queue'),('public','forge_runs'),('public','forge_game_revisions'),('public','player_forecast_lineup_snapshots'),('public','player_forecast_goalie_start_observations'),('public','player_forecast_conflict_resolutions'))
SELECT n.nspname AS schema_name,c.relname AS table_name,t.tgname,t.tgenabled,pg_catalog.pg_get_triggerdef(t.oid,true) AS trigger_definition,
 fn.nspname AS function_schema,p.proname AS function_name,pg_catalog.pg_get_function_identity_arguments(p.oid) AS function_arguments,p.prosecdef AS security_definer,pg_catalog.pg_get_userbyid(p.proowner) AS function_owner,p.proconfig AS settings,
 octet_length(pg_catalog.pg_get_functiondef(p.oid))>65536 AS over_definition_byte_limit,
 CASE WHEN octet_length(pg_catalog.pg_get_functiondef(p.oid))<=65536 THEN pg_catalog.pg_get_functiondef(p.oid) END AS function_definition
FROM target x JOIN pg_catalog.pg_namespace n ON n.nspname=x.schema_name JOIN pg_catalog.pg_class c ON c.relnamespace=n.oid AND c.relname=x.table_name
JOIN pg_catalog.pg_trigger t ON t.tgrelid=c.oid AND NOT t.tgisinternal JOIN pg_catalog.pg_proc p ON p.oid=t.tgfoid JOIN pg_catalog.pg_namespace fn ON fn.oid=p.pronamespace
ORDER BY n.nspname,c.relname,t.tgname LIMIT 65;
COMMIT;
